const { candidateId, candidateName, startAtGate, singleGate } = $input.item.json;

if (!candidateId) throw new Error('candidateId is required');

// Define gate order
const gates = [
  { name: 'kalodata', order: 1, label: 'KaloData Trend Discovery' },
  { name: 'amazon', order: 2, label: 'Amazon Demand Proof' },
  { name: 'aliexpress', order: 3, label: 'AliExpress Economics' },
  { name: 'meta_ads', order: 4, label: 'Meta Ads Competition' },
];

let gatesToRun = gates;
if (singleGate) {
  gatesToRun = gates.filter(g => g.name === singleGate);
} else if (startAtGate && startAtGate > 1) {
  gatesToRun = gates.filter(g => g.order >= startAtGate);
}

return [{
  json: {
    candidateId,
    candidateName: candidateName || `Candidate #${candidateId}`,
    gatesToRun,
    currentGateIndex: 0,
  }
}];

// Run the current gate
const data = $input.item.json;
const gate = data.gatesToRun[data.currentGateIndex];

if (!gate) {
  return [{ json: { ...data, _done: true, message: 'All gates completed' } }];
}

// Gate-specific scrape configurations
const gateConfigs = {
  kalodata: {
    searchQuery: data.candidateName,
    criteria: [
      { name: 'revenue_30d', threshold: 10000, operator: 'gte', label: '30d revenue >= $10k' },
      { name: 'revenue_30d', threshold: 90000, operator: 'lte', label: '30d revenue <= $90k' },
      { name: 'launch_age_days', threshold: 30, operator: 'lte', label: 'Launched within 30 days' },
    ]
  },
  amazon: {
    searchQuery: data.candidateName,
    criteria: [
      { name: 'monthly_sales', threshold: 1000, operator: 'gte', label: '1,000+ monthly sales' },
      { name: 'listing_count', threshold: 2, operator: 'gte', label: 'Multiple listings' },
    ]
  },
  aliexpress: {
    searchQuery: data.candidateName,
    criteria: [
      { name: 'profit_margin', threshold: 20, operator: 'gte', label: 'Margin >= $20' },
      { name: 'weight_kg', threshold: 2, operator: 'lte', label: 'Under 2kg' },
    ]
  },
  meta_ads: {
    searchQuery: data.candidateName,
    criteria: [
      { name: 'active_ads_count', threshold: 1, operator: 'gte', label: 'Has active ads' },
    ]
  },
};

return [{
  json: {
    ...data,
    currentGate: gate,
    gateConfig: gateConfigs[gate.name] || {},
    _done: false,
  }
}];

// ═══════════════════════════════════════════════════════════
// GATE SCRAPER — Real Apify Actor Calls
// Triggers the correct Apify actor per gate, waits for results,
// evaluates pass/fail criteria against actual scraped data.
// ═══════════════════════════════════════════════════════════

const data = $input.item.json;
const gate = data.currentGate;
const config = data.gateConfig;
const APIFY_TOKEN = $env.APIFY_TOKEN;

if (!APIFY_TOKEN) throw new Error('APIFY_TOKEN env var is required');

// ── Actor configs per gate ──────────────────────────────────
const actorConfigs = {
  kalodata: {
    actorId: $env.KALODATA_ACTOR_ID || null,
    waitSeconds: 45,
    buildInput: (name) => ({
      keyword: name,
      sessionCookie: $env.KALODATA_SESSION_ID || '',
      maxProducts: 5,
      proxyConfiguration: { useApifyProxy: true, apifyProxyGroups: ['RESIDENTIAL'] },
    }),
    mapOutput: (items) => {
      const best = items.sort((a, b) => (b.revenue_30d || 0) - (a.revenue_30d || 0))[0] || {};
      return {
        revenue_30d: best.revenue_30d || 0,
        launch_age_days: best.launch_age_days || 999,
      };
    },
  },
  amazon: {
    actorId: 'junglee~free-amazon-product-scraper',
    waitSeconds: 40,
    buildInput: (name) => ({
      queries: [name],
      countryCode: 'US',
      maxItems: 10,
    }),
    mapOutput: (items) => ({
      monthly_sales: items.reduce((sum, i) => sum + (i.monthlySales || i.monthlyRevenue || 0), 0),
      listing_count: items.length,
    }),
  },
  aliexpress: {
    actorId: null,
    waitSeconds: 40,
    buildInput: (name) => ({ query: name, maxItems: 5 }),
    mapOutput: (items) => {
      const best = items[0] || {};
      const price = best.price || best.salePrice || 0;
      return {
        profit_margin: price > 0 ? Math.round(price * 0.6) : null,
        weight_kg: best.weight || null,
      };
    },
  },
  meta_ads: {
    actorId: 'apify~facebook-ads-scraper',
    waitSeconds: 45,
    buildInput: (name) => ({
      startUrls: [{
        url: `https://www.facebook.com/ads/library/?active_status=active&ad_type=all&q=${encodeURIComponent(name)}&country=US&media_type=all`
      }],
      resultsLimit: 30,
    }),
    mapOutput: (items) => ({
      active_ads_count: items.filter(i => i.isActive !== false).length,
    }),
  },
};

// ── Evaluate criteria ───────────────────────────────────────
function evaluateCriteria(criteria, actualData) {
  return criteria.map(c => {
    const actual = actualData[c.name];
    let passed = null;
    if (actual !== null && actual !== undefined) {
      if (c.operator === 'gte') passed = actual >= c.threshold;
      else if (c.operator === 'lte') passed = actual <= c.threshold;
      else if (c.operator === 'eq') passed = actual === c.threshold;
    }
    return { ...c, actualValue: actual, passed };
  });
}

// ── Main execution ──────────────────────────────────────────
const actorConfig = actorConfigs[gate.name];

if (!actorConfig || !actorConfig.actorId) {
  // Actor not deployed — skip this gate with null (not evaluated)
  return [{
    json: {
      ...data,
      scrapeResult: {
        gate: gate.name,
        status: 'actor_not_deployed',
        message: `Actor for ${gate.label} not configured. Set ${gate.name === 'kalodata' ? 'KALODATA_ACTOR_ID' : 'actorId'} to enable.`,
        timestamp: new Date().toISOString(),
      },
      gatePassed: null,
      criteriaResults: config.criteria.map(c => ({ ...c, actualValue: null, passed: null })),
    },
  }];
}

try {
  // 1. Trigger actor run
  const runResponse = await fetch(
    `https://api.apify.com/v2/acts/${actorConfig.actorId}/runs?token=${APIFY_TOKEN}`,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(actorConfig.buildInput(config.searchQuery)),
    }
  );
  const runData = await runResponse.json();
  const runId = runData?.data?.id;

  if (!runId) throw new Error(`Failed to start actor: ${JSON.stringify(runData)}`);

  // 2. Wait for actor to finish
  const waitMs = (actorConfig.waitSeconds || 30) * 1000;
  await new Promise(resolve => setTimeout(resolve, waitMs));

  // 3. Poll until finished (max 3 retries)
  let items = [];
  for (let attempt = 0; attempt < 3; attempt++) {
    const statusRes = await fetch(
      `https://api.apify.com/v2/actor-runs/${runId}?token=${APIFY_TOKEN}`
    );
    const statusData = await statusRes.json();
    const status = statusData?.data?.status;

    if (status === 'SUCCEEDED' || status === 'FAILED' || status === 'ABORTED' || status === 'TIMED-OUT') {
      if (status !== 'SUCCEEDED') {
        throw new Error(`Actor run ${status}: ${gate.label}`);
      }
      // Fetch dataset items
      const itemsRes = await fetch(
        `https://api.apify.com/v2/actor-runs/${runId}/dataset/items?token=${APIFY_TOKEN}&format=json&limit=50`
      );
      items = await itemsRes.json();
      if (!Array.isArray(items)) items = [items];
      break;
    }
    // Still running — wait another 15s
    await new Promise(resolve => setTimeout(resolve, 15000));
  }

  // 4. Map actor output to gate criteria fields
  const mappedData = actorConfig.mapOutput(items);

  // 5. Evaluate criteria
  const criteriaResults = evaluateCriteria(config.criteria, mappedData);
  const allEvaluated = criteriaResults.filter(c => c.passed !== null);
  const gatePassed = allEvaluated.length > 0
    ? allEvaluated.every(c => c.passed === true)
    : null;

  return [{
    json: {
      ...data,
      scrapeResult: {
        gate: gate.name,
        status: 'success',
        runId,
        itemCount: items.length,
        mappedData,
        timestamp: new Date().toISOString(),
      },
      gatePassed,
      criteriaResults,
    },
  }];

} catch (error) {
  return [{
    json: {
      ...data,
      scrapeResult: {
        gate: gate.name,
        status: 'error',
        error: error.message,
        timestamp: new Date().toISOString(),
      },
      gatePassed: null,
      criteriaResults: config.criteria.map(c => ({ ...c, actualValue: null, passed: null })),
    },
  }];
}

// Check if gate passed and decide whether to continue
const prevData = $('Run Gate Scraper').item.json;
const saveResponse = $input.item.json;

// If gate explicitly failed, stop the pipeline
if (prevData.gatePassed === false) {
  return [{
    json: {
      ...prevData,
      _done: true,
      _stoppedAt: prevData.currentGate.name,
      message: `Pipeline stopped: ${prevData.currentGate.label} gate failed`,
    }
  }];
}

// If gate was null (actor not deployed or error), continue to next gate
// Move to next gate
const nextIndex = prevData.currentGateIndex + 1;
return [{
  json: {
    candidateId: prevData.candidateId,
    candidateName: prevData.candidateName,
    gatesToRun: prevData.gatesToRun,
    currentGateIndex: nextIndex,
  }
}];

// All gates completed — trigger scoring
const data = $input.item.json;
return [{
  json: {
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    message: data._stoppedAt
      ? `Pipeline stopped at ${data._stoppedAt} gate`
      : 'All gates completed successfully',
    completedAt: new Date().toISOString(),
  }
}];
